const rawInput = $input.first().json;

// Menangani data dari AI (.output) atau dari Form Manual Direct
const parsed = rawInput.output || rawInput.body || rawInput;

// Ekstraksi Data Mentah & Sanitasi Tipe Data
const weight = Number(parsed.weightGram) || 0;
const hours = Number(parsed.durationHours) || 0;
const isCustomerFilament = parsed.isCustomerFilament === true || parsed.isCustomerFilament === "true";
const rawMaterialType = (parsed.materialType || "PLA").toString().toLowerCase().trim();

// Database Tarif Material & Fixed Addons
const MATERIAL_RATES = { pla: 800, petg: 900 };
const FIXED_ADDON_PRICES = {
  "magnet": 1000,
  "magnet 6x2": 1000,
  "insert nut": 1000,
  "baut": 500
};

let materialRate = 800;
if (isCustomerFilament || rawMaterialType === "customer") {
  materialRate = 0;
} else if (MATERIAL_RATES[rawMaterialType]) {
  materialRate = MATERIAL_RATES[rawMaterialType];
}

// Kalkulasi Biaya Cetak
const materialCost = weight * materialRate;
let machineCost = 0;
if (hours > 0) {
  machineCost = hours <= 1 ? hours * 10000 : 10000 + (hours - 1) * 2640;
}
const printJobSubtotal = Math.round(materialCost + machineCost);

// Pengolahan Itemized Table
const itemizedTable = [];
const displayMaterial = isCustomerFilament ? "Bawa Sendiri" : rawMaterialType.toUpperCase();

itemizedTable.push({
  item: `Jasa Cetak 3D ${displayMaterial} (${weight}g, ${hours} Jam)`,
  qty: 1,
  price: printJobSubtotal,
  subtotal: printJobSubtotal
});

// Normalisasi Addons (Bisa dari Array AI atau Form Manual Single Input)
let addonsList = [];
if (Array.isArray(parsed.addons)) {
  addonsList = parsed.addons;
} else if (parsed.addonItem && parsed.addonItem.trim() !== "") {
  addonsList.push({
    item: parsed.addonItem,
    qty: Number(parsed.addonQty) || 1,
    pricePerItem: Number(parsed.addonPrice) || 0
  });
}

let addonsTotal = 0;
addonsList.forEach(add => {
  const itemName = (add.item || "Addon Item").toString();
  const lowerItemName = itemName.toLowerCase();
  const qty = Number(add.qty) || 1;
  let price = Number(add.pricePerItem) || 0;

  if (price === 0) {
    for (const [key, fixedPrice] of Object.entries(FIXED_ADDON_PRICES)) {
      if (lowerItemName.includes(key)) {
        price = fixedPrice;
        break;
      }
    }
  }

  const sub = qty * price;
  addonsTotal += sub;
  itemizedTable.push({ item: itemName, qty: qty, price: price, subtotal: sub });
});

const grandTotal = Math.round(materialCost + machineCost + addonsTotal);
const formatIDR = (num) => "Rp" + Math.round(num).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");

return {
  clientName: parsed.clientName || "Customer",
  projectName: parsed.projectName || "3D Print Project",
  details: itemizedTable,
  summary: {
    materialType: displayMaterial,
    materialRate: formatIDR(materialRate),
    materialCost: formatIDR(materialCost),
    machineCost: formatIDR(machineCost),
    addonsTotal: formatIDR(addonsTotal),
    grandTotal: formatIDR(grandTotal),
    rawGrandTotal: grandTotal
  }
};

